export async function POST(request: Request) {
    try {
        let updatedCustomersCount = 0;
        let updatedOrdersCount = 0;
        let currentPage = 1;
        let hasNextPage = true;

        console.log("🚀 Starting Paginated Sync...");

        while (hasNextPage) {
            console.log(`📡 Syncing CertControl page ${currentPage}...`);
            const response = await axios.get(`${CERTCONTROL_API_URL}/api/integracao/vendas?page=${currentPage}`, {
                headers: { 'Authorization': `Bearer ${CERTCONTROL_TOKEN}` }
            });

            const sales = response.data.data;
            const meta = response.data.meta;

            if (!Array.isArray(sales)) break;

            for (const sale of sales) {
                const doc = sale.documento?.replace(/\D/g, '');
                if (!doc) continue;

                // --- CUSTOMER UPDATE ---
                const customerPayload: any = {
                    expiry_date: sale.data_vencimento || null,
                    certificate_type: sale.produto || 'Digital',
                    last_contact: new Date().toISOString()
                };

                if (sale.data_vencimento) {
                    const expiryDate = new Date(sale.data_vencimento);
                    const now = new Date();
                    customerPayload.status = expiryDate < now ? 'Vencido' : 'Ativo';
                }

                await supabase.from('customers').update(customerPayload).eq('doc', doc);
                updatedCustomersCount++;

                // --- ORDER UPDATE ---
                const certStatus = sale.status || 'Pendente';
                let deltaStatus = 'Pendente';

                if (['Pago', 'Emitido', 'Concluído', 'Aprovado'].includes(certStatus)) {
                    deltaStatus = 'Pago';
                } else if (certStatus === 'Cancelado') {
                    deltaStatus = 'Cancelado';
                }

                const protocol = sale.numero_pedido ? `PEDIDO - ${sale.numero_pedido}` : (sale.numero_protocolo || `PEDIDO - ${sale.id}`);

                console.log(`🔎 Processing Sale ${sale.id} (${sale.pedido}) | Status: ${certStatus} -> ${deltaStatus}`);

                // Try a more granular update approach to ensure we match
                // We match by ID OR by Document and Protocol string
                const { data: updatedOrder, error: orderError } = await supabase
                    .from('orders')
                    .update({
                        status: deltaStatus,
                        supplier_status: certStatus,
                        supplier_order_id: sale.id.toString(),
                        protocol: protocol
                    })
                    .or(`supplier_order_id.eq.${sale.id},and(doc.eq.${doc},status.eq.Pendente),protocol.ilike.%${sale.id}%,protocol.ilike.%${sale.pedido}%`)
                    .select();

                if (orderError) {
                    console.error(`  🔴 Error updating order for sale ${sale.id}:`, orderError.message);
                } else if (updatedOrder && updatedOrder.length > 0) {
                    console.log(`  ✅ Updated Order ID: ${updatedOrder[0].id} | Protocol: ${updatedOrder[0].protocol}`);
                    updatedOrdersCount++;
                } else {
                    // One last attempt: search by holder_name + doc matching Pendente
                    const { data: lastTry, error: lastError } = await supabase
                        .from('orders')
                        .update({ status: deltaStatus, supplier_status: certStatus, supplier_order_id: sale.id.toString() })
                        .match({ doc: doc, status: 'Pendente' })
                        .select();

                    if (lastTry && lastTry.length > 0) {
                        console.log(`  ✅ Updated Order via doc-match: ${lastTry[0].id}`);
                        updatedOrdersCount++;
                    } else {
                        console.log(`  ⚠️ No matching order found in local DB.`);
                    }
                }
            }

            if (meta && meta.current_page < meta.last_page) {
                currentPage++;
            } else {
                hasNextPage = false;
            }
        }

        return NextResponse.json({
            success: true,
            message: `Sincronização concluída. ${updatedCustomersCount} clientes e ${updatedOrdersCount} pedidos atualizados.`,
            customersCount: updatedCustomersCount,
            ordersCount: updatedOrdersCount
        });

    } catch (error: any) {
        console.error("🔴 Certificate Sync Error:", error.message);
        return NextResponse.json({
            error: "Erro na sincronização: " + (error.response?.data?.message || error.message)
        }, { status: 500 });
    }
}
